topics = {6:'৬ষ্ঠ অধ্যায়: রেখা, কোণ ও ত্রিভুজ',7:'৭ম অধ্যায়: ব্যবহারিক জ্যামিতি',8:'৮ম অধ্যায়: বৃত্ত',14:'১৪শ অধ্যায়: অনুপাত, সদৃশতা ও প্রতিসমতা',15:'১৫শ অধ্যায়: ক্ষেত্রফল সম্পর্কিত উপপাদ্য ও সম্পাদ্য'}
for ch, entries in data.items():
    items=[]
    for i,(text,answer,distractors,solution) in enumerate(entries):
        opts=[str(answer),*[str(x) for x in distractors]]
        shift=(ch+i)%4
        opts=opts[shift:]+opts[:shift]
        items.append(dict(type='MCQ',text=text,options=dict(zip('ABCD',opts)),correct='ABCD'[opts.index(str(answer))],explanation=solution,page=f'Original plain geometry v1 / ch{ch} / Q{i+1:02}',difficulty='EASY' if i%3==0 else 'MEDIUM'))
    batch=dict(category='Class 9',subject='গণিত',topic=topics[ch],book='Proshnobook — নিজস্ব চিত্রবিহীন জ্যামিতি অনুশীলনী',edition='Supplement v1; DRAFT; স্বাধীন শিক্ষক অনুমোদন বাকি',sourceUrl='https://github.com/saifulsirictdev/Proshnobook_com',lang='Bangla',items=items)
    (out/f'ch{ch}-mcq.json').write_text(json.dumps(batch,ensure_ascii=False,indent=2)+'\n')
